const fs = require('fs');
const { spawnSync } = require('child_process');
const runGit = (args) => spawnSync('git', args, { encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 });
const diffResult = runGit(['diff', '--no-ext-diff', '--unified=0', '--']);
const filesResult = runGit(['ls-files', '--others', '--exclude-standard', '-z']);
if (diffResult.status !== 0 || filesResult.status !== 0) {
  process.stdout.write(JSON.stringify({ success: false, exit_code: 1, findings: ['Unable to inspect the complete diff.'], stdout: diffResult.stdout || '', stderr: (diffResult.stderr || '') + (filesResult.stderr || '') }));
  process.exit(0);
}
let content = diffResult.stdout || '';
for (const file of (filesResult.stdout || '').split('\0').filter(Boolean)) {
  try {
    const stat = fs.statSync(file);
    if (stat.isFile() && stat.size <= 2 * 1024 * 1024) content += '\n' + fs.readFileSync(file, 'utf8');
  } catch (_) {
  }
}
const patterns = [
  ['private key', /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/],
  ['AWS access key', /AKIA[0-9A-Z]{16}/],
  ['GitHub token', /gh[opusr]_[A-Za-z0-9_]{30,}/],
  ['OpenAI key', /sk-[A-Za-z0-9_-]{20,}/],
  ['assigned secret value', /(?:client_secret|access_token|refresh_token|api_key|password)\s*[:=]\s*["'][^"'\s]{8,}["']/i],
  ['email address or personal-data candidate', /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i]
];
const findings = patterns.filter((entry) => entry[1].test(content)).map((entry) => entry[0]);
process.stdout.write(JSON.stringify({ success: findings.length === 0, exit_code: findings.length === 0 ? 0 : 1, findings, stdout: '', stderr: '' }));

const fs = require('fs');
const evidence = JSON.parse(fs.readFileSync(0, 'utf8'));
const statuses = [evidence.format, evidence.clippy, evidence.tests, evidence.live_specs, evidence.sensitive_scan];
const allPassed = evidence.review.passed === true && evidence.review.safety_passed === true && statuses.every((status) => status.success === true && status.exit_code === 0);
process.stdout.write(JSON.stringify({ all_passed: allPassed, evidence }));

const fs = require('fs');
const status = JSON.parse(fs.readFileSync(0, 'utf8'));
process.stdout.write(JSON.stringify({ all_passed: status.success === true && status.exit_code === 0, evidence: status }));

const fs = require('fs');
const payload = JSON.parse(fs.readFileSync(0, 'utf8'));
const expectations = payload.expectations;
const plan = payload.exercise.generated_plan;
if (!Array.isArray(expectations)) {
  process.stderr.write('expectations must be an array\n');
  process.exit(1);
}
const decodeToken = (token) => token.replace(/~1/g, '/').replace(/~0/g, '~');
const readPointer = (value, pointer) => {
  if (pointer === '') return { found: true, value };
  if (typeof pointer !== 'string' || !pointer.startsWith('/')) return { found: false };
  let current = value;
  for (const rawToken of pointer.slice(1).split('/')) {
    const token = decodeToken(rawToken);
    if (current === null || typeof current !== 'object' || !Object.prototype.hasOwnProperty.call(current, token)) return { found: false };
    current = current[token];
  }
  return { found: true, value: current };
};
const equal = (left, right) => JSON.stringify(left) === JSON.stringify(right);
const evidence = expectations.map((expectation, index) => {
  if (expectation === null || typeof expectation !== 'object' || typeof expectation.pointer !== 'string' || !Object.prototype.hasOwnProperty.call(expectation, 'expected')) {
    return { index, matched: false, error: 'Expectation must contain pointer and expected fields.' };
  }
  const actual = readPointer(plan, expectation.pointer);
  return {
    index,
    pointer: expectation.pointer,
    expected: expectation.expected,
    found: actual.found,
    actual: actual.found ? actual.value : null,
    matched: actual.found && equal(actual.value, expectation.expected)
  };
});
process.stdout.write(JSON.stringify({ all_matched: evidence.every((item) => item.matched), evidence }));

const { spawnSync } = require('child_process');
const run = (args) => spawnSync('git', args, { encoding: 'utf8' });
const status = run(['status', '--short']);
const stat = run(['diff', '--stat']);
const names = run(['diff', '--name-status']);
if (status.status !== 0 || stat.status !== 0 || names.status !== 0) process.exit(1);
process.stdout.write(JSON.stringify({ status: status.stdout, stat: stat.stdout, changed_files: names.stdout }));

